<?php require_once __DIR__.'/includes/functions.php'; if (is_logged_in()) redirect('dashboard.php'); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $email=trim($_POST['email']??''); $password=$_POST['password']??'';
try {$pdo=db(); $s=$pdo->prepare("SELECT * FROM users WHERE email=? AND is_active=1 LIMIT 1"); $s->execute([$email]); $u=$s->fetch();
if($u && password_verify($password,$u['password_hash'])) { $_SESSION['user']=$u; redirect('dashboard.php'); } $error='Email atau password salah.';} catch(Throwable $e){$error='Database belum siap. Import database/sablonic.sql dan cek config/database.php.';}}
